INSERT OR IGNORE INTO grammar_points (id,textbook_id,unit_id,name,explanation,structure,usage_condition,original_examples,common_errors,verification_status,created_at,updated_at) VALUES ('pep_new_g6_s1_g1','pep_new_g6_s1','pep_new_g6_s1_u1','一般过去时：特殊疑问句','询问已经发生的旅行和活动','What/Where + did + 主语 + 动词原形?','询问已经发生的旅行和活动','What did you do? I climbed the Great Wall.','did 后面的动词要用原形。','verified',datetime('now'),datetime('now'));
INSERT OR IGNORE INTO grammar_points (id,textbook_id,unit_id,name,explanation,structure,usage_condition,original_examples,common_errors,verification_status,created_at,updated_at) VALUES ('pep_new_g6_s1_g2','pep_new_g6_s1','pep_new_g6_s1_u2','一般过去时：一般疑问句','询问过去是否做过某事','Did + 主语 + 动词原形?','询问过去是否做过某事','Did you eat mooncakes? Yes, we did.','不要在 did 后继续使用过去式。','verified',datetime('now'),datetime('now'));
INSERT OR IGNORE INTO grammar_points (id,textbook_id,unit_id,name,explanation,structure,usage_condition,original_examples,common_errors,verification_status,created_at,updated_at) VALUES ('pep_new_g6_s1_g3','pep_new_g6_s1','pep_new_g6_s1_u3','should 提建议','给出健康建议','主语 + should/shouldn’t + 动词原形','给出健康建议','You should see a doctor.','should 后使用动词原形。','verified',datetime('now'),datetime('now'));
INSERT OR IGNORE INTO grammar_points (id,textbook_id,unit_id,name,explanation,structure,usage_condition,original_examples,common_errors,verification_status,created_at,updated_at) VALUES ('pep_new_g6_s1_g4','pep_new_g6_s1','pep_new_g6_s1_u4','be going to 表示计划','说明将来的消费计划','主语 + be going to + 动词原形','说明将来的消费计划','I am going to buy a schoolbag.','根据主语选择 am/is/are。','verified',datetime('now'),datetime('now'));
INSERT OR IGNORE INTO grammar_points (id,textbook_id,unit_id,name,explanation,structure,usage_condition,original_examples,common_errors,verification_status,created_at,updated_at) VALUES ('pep_new_g6_s1_g5','pep_new_g6_s1','pep_new_g6_s1_u5','there be 句型','描述宇宙和自然中存在的事物','There is/are + 名词 + 地点','描述宇宙和自然中存在的事物','There are many stars in the sky.','单数用 is，复数用 are。','verified',datetime('now'),datetime('now'));
INSERT OR IGNORE INTO grammar_points (id,textbook_id,unit_id,name,explanation,structure,usage_condition,original_examples,common_errors,verification_status,created_at,updated_at) VALUES ('pep_new_g6_s1_g6','pep_new_g6_s1','pep_new_g6_s1_u6','情态动词与环保建议','表达节能和环保建议','主语 + should/can + 动词原形','表达节能和环保建议','We should save water.','情态动词后使用动词原形。','verified',datetime('now'),datetime('now'));
